-- ============================================================
-- FERTILITY PACKAGES MODULE
-- Run in Supabase SQL Editor for project: rjmuhomeqydszmerlqrh
--
-- Adds:
--   1. public.fertility_packages               — CMS-managed package catalogue
--   2. public.fertility_package_testimonials   — approved, consented reviews
--   3. public.analytics_events                 — first-party product analytics
--   4. Attribution + booking columns on public.leads
--   5. Seed rows for the six launch packages
--
-- ⚠ COMMERCIAL / CLINICAL PLACEHOLDERS
--   Every seeded package has price = NULL and price_status = 'placeholder'; no
--   pricing has been invented. Inclusions reflect only the scope supplied in the
--   Conceev brief and every row carries content_status = 'pending_clinical_review'
--   until a clinician signs it off. Update both before launch.
--
-- Safe to re-run: all statements are IF NOT EXISTS / ON CONFLICT guarded.
-- ============================================================


-- ── 1. FERTILITY PACKAGES ─────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.fertility_packages (
  id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug                    text NOT NULL UNIQUE,
  name                    text NOT NULL,
  category                text NOT NULL DEFAULT '',
  tagline                 text NOT NULL DEFAULT '',
  short_description       text NOT NULL DEFAULT '',
  long_description        text NOT NULL DEFAULT '',
  hero_title              text NOT NULL DEFAULT '',
  hero_description        text NOT NULL DEFAULT '',

  audience                text NOT NULL DEFAULT 'individual'
                            CHECK (audience IN ('individual','couple','either')),
  ideal_for_label         text NOT NULL DEFAULT '',
  ideal_for               jsonb NOT NULL DEFAULT '[]'::jsonb,
  intents                 text[] NOT NULL DEFAULT '{}',

  -- Commercials. price stays NULL while price_status = 'placeholder'; the UI
  -- renders price_placeholder_label instead of a number.
  price                   numeric(12,2),
  compare_at_price        numeric(12,2),
  price_status            text NOT NULL DEFAULT 'placeholder'
                            CHECK (price_status IN ('confirmed','placeholder')),
  discount_label          text,
  currency                text NOT NULL DEFAULT 'INR',
  price_placeholder_label text NOT NULL DEFAULT 'Pricing on request',

  status                  text NOT NULL DEFAULT 'draft'
                            CHECK (status IN ('published','draft')),
  featured                boolean NOT NULL DEFAULT false,
  badge                   text,
  duration                text,
  availability_type       text NOT NULL DEFAULT 'in_clinic'
                            CHECK (availability_type IN ('in_clinic','at_home','online','hybrid')),
  locations               text[] NOT NULL DEFAULT '{}',
  variants                jsonb NOT NULL DEFAULT '[]'::jsonb,

  inclusions              jsonb NOT NULL DEFAULT '[]'::jsonb,
  exclusions              text[] NOT NULL DEFAULT '{}',
  what_you_learn          text[] NOT NULL DEFAULT '{}',
  how_it_works            jsonb NOT NULL DEFAULT '[]'::jsonb,
  faqs                    jsonb NOT NULL DEFAULT '[]'::jsonb,
  comparison              jsonb NOT NULL DEFAULT '{}'::jsonb,

  icon                    text NOT NULL DEFAULT 'Sparkles',
  content_status          text NOT NULL DEFAULT 'pending_clinical_review'
                            CHECK (content_status IN ('clinically_approved','pending_clinical_review')),
  seo                     jsonb NOT NULL DEFAULT '{}'::jsonb,
  display_order           integer NOT NULL DEFAULT 0,

  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now(),

  -- A published package must never carry an unpriced "confirmed" price.
  CONSTRAINT fertility_packages_price_consistency
    CHECK (price_status = 'placeholder' OR price IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS idx_fertility_packages_status
  ON public.fertility_packages(status, display_order);
CREATE INDEX IF NOT EXISTS idx_fertility_packages_slug
  ON public.fertility_packages(slug);

ALTER TABLE public.fertility_packages ENABLE ROW LEVEL SECURITY;

-- Public may read published packages only; drafts stay admin-only.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public'
                 AND tablename='fertility_packages' AND policyname='fertility_packages_public_read') THEN
    CREATE POLICY "fertility_packages_public_read" ON public.fertility_packages
      FOR SELECT USING (status = 'published');
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public'
                 AND tablename='fertility_packages' AND policyname='fertility_packages_admin_all') THEN
    CREATE POLICY "fertility_packages_admin_all" ON public.fertility_packages
      FOR ALL TO authenticated
      USING ((auth.jwt() -> 'app_metadata' ->> 'role') IN ('admin','superadmin'))
      WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') IN ('admin','superadmin'));
  END IF;
END $$;

-- Body is $fn$-quoted so it never collides with the surrounding DO $$ blocks.
CREATE OR REPLACE FUNCTION public.touch_fertility_package()
RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$fn$;

DROP TRIGGER IF EXISTS trg_touch_fertility_package ON public.fertility_packages;
CREATE TRIGGER trg_touch_fertility_package
  BEFORE UPDATE ON public.fertility_packages
  FOR EACH ROW EXECUTE FUNCTION public.touch_fertility_package();


-- ── 2. PACKAGE TESTIMONIALS ───────────────────────────────────────────────────
-- Intentionally seeded EMPTY. No sample or placeholder testimonials are created;
-- the UI omits the section entirely until real, consented entries are approved.
CREATE TABLE IF NOT EXISTS public.fertility_package_testimonials (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  package_id    uuid NOT NULL REFERENCES public.fertility_packages(id) ON DELETE CASCADE,
  display_name  text NOT NULL,
  age           integer CHECK (age IS NULL OR (age > 0 AND age < 120)),
  journey       text,
  rating        numeric(2,1) NOT NULL DEFAULT 5.0 CHECK (rating >= 1 AND rating <= 5),
  quote         text NOT NULL,
  -- Consent must be recorded before anything is published.
  consent_given boolean NOT NULL DEFAULT false,
  is_approved   boolean NOT NULL DEFAULT false,
  display_order integer NOT NULL DEFAULT 0,
  created_at    timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT testimonial_requires_consent
    CHECK (is_approved = false OR consent_given = true)
);

CREATE INDEX IF NOT EXISTS idx_fertility_testimonials_package
  ON public.fertility_package_testimonials(package_id, is_approved, display_order);

ALTER TABLE public.fertility_package_testimonials ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public'
                 AND tablename='fertility_package_testimonials' AND policyname='fertility_testimonials_public_read') THEN
    CREATE POLICY "fertility_testimonials_public_read" ON public.fertility_package_testimonials
      FOR SELECT USING (is_approved = true);
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public'
                 AND tablename='fertility_package_testimonials' AND policyname='fertility_testimonials_admin_all') THEN
    CREATE POLICY "fertility_testimonials_admin_all" ON public.fertility_package_testimonials
      FOR ALL TO authenticated
      USING ((auth.jwt() -> 'app_metadata' ->> 'role') IN ('admin','superadmin'))
      WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') IN ('admin','superadmin'));
  END IF;
END $$;


-- ── 3. ANALYTICS EVENTS ───────────────────────────────────────────────────────
-- First-party event store written by src/lib/analytics.ts. Deliberately holds NO
-- patient-identifying data: names, phone numbers and emails belong on `leads`,
-- never here.
CREATE TABLE IF NOT EXISTS public.analytics_events (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_name    text NOT NULL,
  properties    jsonb NOT NULL DEFAULT '{}'::jsonb,
  page_path     text,
  session_id    text,
  device_type   text,
  browser       text,
  utm_source    text,
  utm_medium    text,
  utm_campaign  text,
  utm_term      text,
  utm_content   text,
  landing_page  text,
  referrer      text,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_analytics_events_name_time
  ON public.analytics_events(event_name, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_analytics_events_session
  ON public.analytics_events(session_id);

ALTER TABLE public.analytics_events ENABLE ROW LEVEL SECURITY;

-- Anonymous visitors may write events but can never read them back.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public'
                 AND tablename='analytics_events' AND policyname='analytics_events_public_insert') THEN
    CREATE POLICY "analytics_events_public_insert" ON public.analytics_events
      FOR INSERT WITH CHECK (true);
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public'
                 AND tablename='analytics_events' AND policyname='analytics_events_admin_read') THEN
    CREATE POLICY "analytics_events_admin_read" ON public.analytics_events
      FOR SELECT TO authenticated
      USING ((auth.jwt() -> 'app_metadata' ->> 'role') IN ('admin','superadmin'));
  END IF;
END $$;


-- ── 4. LEADS: package + attribution columns ───────────────────────────────────
-- Extends the existing leads pipeline rather than creating a parallel booking
-- store, so package enquiries land with every other lead.
ALTER TABLE public.leads
  ADD COLUMN IF NOT EXISTS package_slug             text,
  ADD COLUMN IF NOT EXISTS package_name             text,
  ADD COLUMN IF NOT EXISTS package_variant          text,
  ADD COLUMN IF NOT EXISTS preferred_date           date,
  ADD COLUMN IF NOT EXISTS preferred_time           text,
  ADD COLUMN IF NOT EXISTS consultation_preference  text,
  ADD COLUMN IF NOT EXISTS partner_name             text,
  ADD COLUMN IF NOT EXISTS partner_phone            text,
  ADD COLUMN IF NOT EXISTS consent_given            boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS consent_given_at         timestamptz,
  -- Marketing attribution
  ADD COLUMN IF NOT EXISTS utm_source               text,
  ADD COLUMN IF NOT EXISTS utm_medium               text,
  ADD COLUMN IF NOT EXISTS utm_campaign             text,
  ADD COLUMN IF NOT EXISTS utm_term                 text,
  ADD COLUMN IF NOT EXISTS utm_content              text,
  ADD COLUMN IF NOT EXISTS landing_page             text,
  ADD COLUMN IF NOT EXISTS referrer                 text,
  ADD COLUMN IF NOT EXISTS device_type              text,
  ADD COLUMN IF NOT EXISTS browser                  text,
  ADD COLUMN IF NOT EXISTS first_touch_source       text,
  ADD COLUMN IF NOT EXISTS first_touch_medium       text,
  ADD COLUMN IF NOT EXISTS first_touch_campaign     text,
  ADD COLUMN IF NOT EXISTS last_touch_source        text,
  ADD COLUMN IF NOT EXISTS last_touch_medium        text,
  ADD COLUMN IF NOT EXISTS last_touch_campaign      text;

CREATE INDEX IF NOT EXISTS idx_leads_package_slug ON public.leads(package_slug);
CREATE INDEX IF NOT EXISTS idx_leads_utm_campaign ON public.leads(utm_campaign);


-- ── 5. SEED: launch packages ──────────────────────────────────────────────────
-- Generated from src/data/fertilityPackages.ts via
--   npx vite-node scripts/generate-fertility-package-seed.ts
-- Re-run that script and replace this block whenever the catalogue changes.

INSERT INTO public.fertility_packages (
  slug, name, category, tagline, short_description, long_description, hero_title, hero_description, audience, ideal_for_label, ideal_for, intents, price, compare_at_price, price_status, discount_label, currency, price_placeholder_label, status, featured, badge, duration, availability_type, locations, variants, inclusions, exclusions, what_you_learn, how_it_works, faqs, comparison, icon, content_status, seo, display_order
) VALUES
('fertility-health-check', 'Fertility Health Check', 'Fertility Assessment', 'Start with a baseline', 'A first look at your reproductive health, reviewed with a fertility specialist.', 'If you have never had your fertility looked at, this is the place to begin. The Fertility Health Check combines a consultation, an ovarian reserve assessment and relevant blood investigations, then puts the results in front of a fertility specialist who explains what they may mean for you. It is a starting point, not a verdict — and it is designed for women who simply want to know where they stand.', 'Know where your fertility stands today', 'A baseline fertility assessment with specialist interpretation, so you''re working from information rather than guesswork.', 'individual', 'Women wanting a fertility baseline', '[{"title":"You want to understand your fertility","description":"Not because something is wrong — because you''d rather know.","icon":"Compass"},{"title":"You''re thinking about pregnancy","description":"Now, or somewhere in the next few years.","icon":"CalendarHeart"},{"title":"You''ve never been assessed before","description":"And you want a clear, unhurried starting point.","icon":"Sparkles"},{"title":"You want a baseline to track","description":"Something to compare against if you reassess later.","icon":"TrendingUp"}]'::jsonb, ARRAY['understand', 'plan-pregnancy']::text[], NULL, NULL, 'placeholder', NULL, 'INR', 'Pricing on request', 'published', false, 'Best first step', 'Single visit', 'in_clinic', ARRAY['Bangalore', 'Hyderabad']::text[], '[]'::jsonb, '[{"id":"female-fertility","title":"Female fertility","subtitle":"Your baseline reproductive assessment.","variant":"default","items":[{"id":"amh","label":"AMH / ovarian reserve assessment","description":"A blood marker that may help indicate how many eggs remain available — one part of the fertility picture, not the whole of it.","icon":"FlaskConical"},{"id":"repro-health","label":"Basic reproductive health evaluation","description":"A structured review of your cycle, history and symptoms with a fertility specialist.","icon":"HeartPulse"},{"id":"bloods","label":"Relevant blood investigations","description":"Blood work selected for your situation, so you''re not paying for tests you don''t need.","icon":"TestTube"}]},{"id":"expert-care","title":"Expert care","subtitle":"The part that turns numbers into a plan.","variant":"default","items":[{"id":"specialist-consultation","label":"Fertility specialist consultation","description":"Time with a specialist to talk through your history and your questions.","icon":"Stethoscope"},{"id":"results-review","label":"Results review","description":"Your results explained in plain language, not handed over as a printout.","icon":"ClipboardCheck"},{"id":"next-steps","label":"Personalised next-step recommendation","description":"A clear view of what may be worth considering, and what can wait.","icon":"Route"}]}]'::jsonb, ARRAY['Fertility treatment (IVF, IUI, ICSI) — quoted separately if you choose to proceed', 'Medication and prescriptions', 'Investigations beyond those listed, unless agreed with you in advance', 'Treatment at partner hospitals arranged under a separate care plan']::text[], ARRAY['An indication of your ovarian reserve', 'How your cycle and history fit into the wider fertility picture', 'Whether any of your results may warrant further evaluation', 'Which next steps are worth discussing with your specialist', 'What a realistic timeline could look like for you']::text[], '[{"step":"01","title":"Choose your package","description":"Pick the assessment that matches where you are today. Not sure? Our care team can help you decide."},{"step":"02","title":"Book your appointment","description":"Share your details and a care coordinator confirms your slot, location and any preparation you need."},{"step":"03","title":"Complete your assessment","description":"Attend your visit. Your coordinator tells you exactly what to expect before you arrive."},{"step":"04","title":"Meet your expert","description":"A fertility specialist reviews your results with you and explains the next steps worth discussing."}]'::jsonb, '[{"question":"Who is this package for?","answer":"Women who want a baseline understanding of their reproductive health — whether they''re planning pregnancy soon, thinking about it for later, or simply want to know where they stand."},{"question":"When in my cycle should I book?","answer":"Some fertility investigations are best done on specific cycle days. Your care coordinator asks about your cycle when you book and schedules your appointment accordingly."},{"question":"Do I need a doctor''s referral to book?","answer":"No referral is needed. You can book any assessment directly, and a fertility specialist reviews your results with you afterwards."},{"question":"Do I need to fast before my tests?","answer":"It depends on which investigations are included for you. Your care coordinator confirms any fasting or cycle-day requirements when your appointment is scheduled, so you are never left guessing."},{"question":"When will I receive my results?","answer":"Turnaround varies by investigation and by lab. Your coordinator gives you an expected timeline at the time of booking and lets you know as soon as your results are ready for review."},{"question":"How long does the appointment take?","answer":"Your coordinator shares the expected duration for your specific appointment when you book, along with the location and anything you need to bring."},{"question":"Can I add additional tests?","answer":"Yes. If your specialist feels further evaluation may be useful, additional investigations can be discussed and arranged. Any additional cost is confirmed with you before anything is carried out."},{"question":"Does this package include treatment?","answer":"No. These are assessment and consultation packages. They may help you and your specialist understand your situation and decide what to consider next — any treatment is quoted and consented to separately."},{"question":"Does this package guarantee pregnancy?","answer":"No. No assessment can guarantee pregnancy, and no test can detect every possible fertility factor. These packages are designed to give you and your specialist clearer information to work from."},{"question":"Can I book a consultation after receiving my results?","answer":"Yes. A results review with a fertility specialist is part of every assessment package, and you can book further consultations at any point."}]'::jsonb, '{"ideal_for":"A first fertility baseline","female_assessment":true,"male_assessment":false,"amh":true,"hormonal_evaluation":"conditional","ultrasound_afc":false,"semen_analysis":false,"specialist_consultation":true,"results_review":true,"personalised_plan":true,"availability":"In-clinic","locations":"Bangalore, Hyderabad"}'::jsonb, 'Compass', 'pending_clinical_review', '{"title":"Fertility Health Check in Bangalore & Hyderabad | Conceev Health","description":"A baseline fertility assessment with AMH, relevant blood investigations and a fertility specialist review. Understand your reproductive health with Conceev Health.","keywords":["fertility health check","fertility test bangalore","AMH test","ovarian reserve test","fertility assessment hyderabad"],"og_title":"Fertility Health Check | Conceev Health","og_description":"Understand your fertility baseline with specialist-reviewed testing at Conceev Health.","og_image":null,"schema_type":"Service"}'::jsonb, 1),
('complete-fertility-assessment', 'Complete Fertility Assessment', 'Fertility Assessment', 'A deeper evaluation', 'A more comprehensive look at your reproductive health, hormones and fertility status.', 'Where the Fertility Health Check gives you a baseline, the Complete Fertility Assessment goes further. It adds a broader hormonal evaluation and, where clinically appropriate, thyroid-related fertility markers, metabolic assessment and an ultrasound with antral follicle count. Everything is reviewed by a fertility specialist who builds you a personalised fertility roadmap rather than handing over a stack of numbers.', 'A deeper look at your reproductive health', 'Our most comprehensive individual assessment, combining ovarian reserve, hormonal evaluation and specialist review into one personalised fertility roadmap.', 'individual', 'Women wanting a comprehensive evaluation', '[{"title":"You''ve been trying to conceive","description":"And you want a fuller picture than a single marker can give.","icon":"CalendarHeart"},{"title":"Your cycle has changed","description":"Irregularity, new symptoms, or something that doesn''t feel right.","icon":"Activity"},{"title":"A basic check raised questions","description":"You want the broader evaluation that answers them.","icon":"FileSearch"},{"title":"You''re planning IVF or IUI","description":"And want a thorough assessment before deciding anything.","icon":"Route"}]'::jsonb, ARRAY['understand', 'plan-pregnancy', 'second-opinion']::text[], NULL, NULL, 'placeholder', NULL, 'INR', 'Pricing on request', 'published', true, 'Most Popular', 'Single visit', 'in_clinic', ARRAY['Bangalore', 'Hyderabad']::text[], '[]'::jsonb, '[{"id":"female-fertility","title":"Female fertility","subtitle":"A broader reproductive and hormonal evaluation.","variant":"default","items":[{"id":"ovarian-reserve","label":"Ovarian reserve assessment","description":"May help indicate the number of eggs still available to you.","icon":"FlaskConical"},{"id":"hormonal","label":"Hormonal evaluation","description":"A wider hormone panel that can provide insight into ovulation and cycle regulation.","icon":"TestTube"},{"id":"thyroid","label":"Thyroid-related fertility markers","description":"Included where clinically appropriate — thyroid function can influence cycles and conception.","icon":"Waves","conditional":true},{"id":"metabolic","label":"Metabolic assessment","description":"Included where clinically appropriate, as metabolic health can be relevant to fertility.","icon":"Activity","conditional":true},{"id":"ultrasound","label":"Ultrasound / antral follicle count","description":"A scan that helps your specialist assess follicle numbers, where included in your plan.","icon":"Scan","conditional":true}]},{"id":"expert-care","title":"Expert care","subtitle":"The part that turns numbers into a plan.","variant":"default","items":[{"id":"specialist-consultation","label":"Fertility specialist consultation","description":"Time with a specialist to talk through your history and your questions.","icon":"Stethoscope"},{"id":"doctor-review","label":"Doctor review","description":"A fertility specialist interprets your full set of results together, not in isolation.","icon":"ClipboardCheck"},{"id":"roadmap","label":"Personalised fertility roadmap","description":"What your results may mean, what to consider next, and on what timeline.","icon":"Route"}]}]'::jsonb, ARRAY['Fertility treatment (IVF, IUI, ICSI) — quoted separately if you choose to proceed', 'Medication and prescriptions', 'Investigations beyond those listed, unless agreed with you in advance', 'Treatment at partner hospitals arranged under a separate care plan']::text[], ARRAY['An indication of your ovarian reserve', 'How your hormonal health may be affecting your cycle', 'Key fertility factors relevant to your situation', 'Whether further evaluation may be useful', 'Which next steps to discuss with your specialist']::text[], '[{"step":"01","title":"Choose your package","description":"Pick the assessment that matches where you are today. Not sure? Our care team can help you decide."},{"step":"02","title":"Book your appointment","description":"Share your details and a care coordinator confirms your slot, location and any preparation you need."},{"step":"03","title":"Complete your assessment","description":"Attend your visit. Your coordinator tells you exactly what to expect before you arrive."},{"step":"04","title":"Meet your expert","description":"A fertility specialist reviews your results with you and explains the next steps worth discussing."}]'::jsonb, '[{"question":"How is this different from the Fertility Health Check?","answer":"The Fertility Health Check gives you a baseline: ovarian reserve, relevant bloods and a specialist review. The Complete Fertility Assessment adds a broader hormonal evaluation and — where clinically appropriate — thyroid-related markers, metabolic assessment and an ultrasound with antral follicle count, finishing with a personalised fertility roadmap."},{"question":"Which tests will actually be included for me?","answer":"Your specialist confirms the exact investigations based on your history, cycle and symptoms. Items marked ''where clinically appropriate'' are included only when they may add something useful for you."},{"question":"Do I need a doctor''s referral to book?","answer":"No referral is needed. You can book any assessment directly, and a fertility specialist reviews your results with you afterwards."},{"question":"Do I need to fast before my tests?","answer":"It depends on which investigations are included for you. Your care coordinator confirms any fasting or cycle-day requirements when your appointment is scheduled, so you are never left guessing."},{"question":"When will I receive my results?","answer":"Turnaround varies by investigation and by lab. Your coordinator gives you an expected timeline at the time of booking and lets you know as soon as your results are ready for review."},{"question":"How long does the appointment take?","answer":"Your coordinator shares the expected duration for your specific appointment when you book, along with the location and anything you need to bring."},{"question":"Can I add additional tests?","answer":"Yes. If your specialist feels further evaluation may be useful, additional investigations can be discussed and arranged. Any additional cost is confirmed with you before anything is carried out."},{"question":"Does this package include treatment?","answer":"No. These are assessment and consultation packages. They may help you and your specialist understand your situation and decide what to consider next — any treatment is quoted and consented to separately."},{"question":"Does this package guarantee pregnancy?","answer":"No. No assessment can guarantee pregnancy, and no test can detect every possible fertility factor. These packages are designed to give you and your specialist clearer information to work from."},{"question":"Can I book a consultation after receiving my results?","answer":"Yes. A results review with a fertility specialist is part of every assessment package, and you can book further consultations at any point."}]'::jsonb, '{"ideal_for":"A comprehensive individual evaluation","female_assessment":true,"male_assessment":false,"amh":true,"hormonal_evaluation":true,"ultrasound_afc":"conditional","semen_analysis":false,"specialist_consultation":true,"results_review":true,"personalised_plan":true,"availability":"In-clinic","locations":"Bangalore, Hyderabad"}'::jsonb, 'Microscope', 'pending_clinical_review', '{"title":"Complete Fertility Assessment | Conceev Health","description":"A comprehensive fertility evaluation covering ovarian reserve, hormonal assessment and specialist review, ending with a personalised fertility roadmap.","keywords":["complete fertility assessment","comprehensive fertility test","hormonal evaluation fertility","antral follicle count","fertility roadmap"],"og_title":"Complete Fertility Assessment | Conceev Health","og_description":"A deeper look at your reproductive health, reviewed by a fertility specialist.","og_image":null,"schema_type":"Service"}'::jsonb, 2),
('couples-fertility-assessment', 'Couples Fertility Assessment', 'Couples Assessment', 'Fertility takes two', 'Assess both partners together, so you''re not solving half the picture.', 'Fertility is rarely a one-person question, yet it is often investigated as though it were. This assessment looks at both partners in parallel — a female fertility assessment on one side, a semen analysis and male fertility evaluation on the other — then brings the two together in a single consultation with a fertility specialist. You leave with one shared understanding and one shared plan.', 'Fertility takes two. Start by understanding both sides.', 'A parallel assessment for both partners, reviewed together in one consultation with a fertility specialist.', 'couple', 'Couples assessing together', '[{"title":"You''re trying to conceive","description":"And want to understand both sides rather than one.","icon":"Users"},{"title":"You''ve been trying for a while","description":"Without a clear explanation so far.","icon":"Clock"},{"title":"You''re planning ahead together","description":"You don''t have to be struggling to get checked.","icon":"CalendarHeart"},{"title":"You want one shared plan","description":"Not two separate appointments and two separate reports.","icon":"Route"}]'::jsonb, ARRAY['both-partners', 'plan-pregnancy', 'understand']::text[], NULL, NULL, 'placeholder', NULL, 'INR', 'Pricing on request', 'published', true, 'Best for Couples', 'Single visit for both partners', 'in_clinic', ARRAY['Bangalore', 'Hyderabad']::text[], '[]'::jsonb, '[{"id":"for-her","title":"For her","subtitle":"Female fertility assessment","variant":"her","items":[{"id":"female-assessment","label":"Female fertility assessment","description":"A structured review of your cycle, history and reproductive health with a specialist.","icon":"HeartPulse"},{"id":"ovarian-reserve","label":"Ovarian reserve assessment","description":"May help indicate how many eggs remain available.","icon":"FlaskConical"},{"id":"hormonal","label":"Relevant hormonal evaluation","description":"Hormone testing selected for your situation, which can provide insight into ovulation.","icon":"TestTube"},{"id":"ultrasound","label":"Ultrasound / antral follicle count","description":"A scan to help assess follicle numbers, where applicable to your assessment.","icon":"Scan","conditional":true}]},{"id":"for-him","title":"For him","subtitle":"Male fertility assessment","variant":"him","items":[{"id":"semen-analysis","label":"Semen analysis","description":"Looks at count, motility and morphology — the most direct male fertility investigation.","icon":"Microscope"},{"id":"male-evaluation","label":"Male fertility evaluation","description":"A clinical review of history and lifestyle factors that may be relevant.","icon":"ClipboardCheck"},{"id":"additional-male","label":"Additional tests","description":"Further male investigations where clinically appropriate, agreed with you first.","icon":"TestTube","conditional":true}]},{"id":"together","title":"Together","subtitle":"One consultation, one plan","variant":"together","items":[{"id":"joint-consultation","label":"Fertility specialist consultation","description":"You attend together, so nothing gets relayed second-hand.","icon":"Stethoscope"},{"id":"joint-review","label":"Results review","description":"Both sets of results explained side by side, in plain language.","icon":"ClipboardCheck"},{"id":"couple-plan","label":"Couple-focused next-step plan","description":"One shared plan you both understand and agree on.","icon":"Route"}]}]'::jsonb, ARRAY['Fertility treatment (IVF, IUI, ICSI) — quoted separately if you choose to proceed', 'Medication and prescriptions', 'Investigations beyond those listed, unless agreed with you in advance', 'Treatment at partner hospitals arranged under a separate care plan']::text[], ARRAY['An indication of her ovarian reserve and hormonal health', 'What his semen analysis may suggest about male fertility factors', 'How both sets of results fit together', 'Whether further evaluation may be useful for either partner', 'Which next steps to discuss as a couple with your specialist']::text[], '[{"step":"01","title":"Choose your package","description":"Pick the assessment that matches where you are today. Not sure? Our care team can help you decide."},{"step":"02","title":"Book one appointment for both","description":"Your coordinator schedules both partners into the same visit and confirms any preparation each of you needs."},{"step":"03","title":"Attend together","description":"Her assessment and his assessment happen in the same visit, so you''re not making two separate trips."},{"step":"04","title":"Review as a couple","description":"A fertility specialist takes you both through the combined results and what may be worth considering next."}]'::jsonb, '[{"question":"Do we both need to attend the same appointment?","answer":"It''s designed that way, and it''s usually simpler. If one of you can''t make the scheduled slot, your care coordinator can arrange the two assessments separately and still bring the results together for a joint review."},{"question":"Does this mean we need IVF?","answer":"No. This is an assessment, not a treatment pathway. It''s designed to help you both understand where you stand, and treatment is only discussed if and when it becomes relevant to you."},{"question":"Can my partner come with me?","answer":"Yes — this package is built around both partners attending together, and the consultation is designed for the two of you."},{"question":"Do I need a doctor''s referral to book?","answer":"No referral is needed. You can book any assessment directly, and a fertility specialist reviews your results with you afterwards."},{"question":"Do I need to fast before my tests?","answer":"It depends on which investigations are included for you. Your care coordinator confirms any fasting or cycle-day requirements when your appointment is scheduled, so you are never left guessing."},{"question":"When will I receive my results?","answer":"Turnaround varies by investigation and by lab. Your coordinator gives you an expected timeline at the time of booking and lets you know as soon as your results are ready for review."},{"question":"How long does the appointment take?","answer":"Your coordinator shares the expected duration for your specific appointment when you book, along with the location and anything you need to bring."},{"question":"Can I add additional tests?","answer":"Yes. If your specialist feels further evaluation may be useful, additional investigations can be discussed and arranged. Any additional cost is confirmed with you before anything is carried out."},{"question":"Does this package include treatment?","answer":"No. These are assessment and consultation packages. They may help you and your specialist understand your situation and decide what to consider next — any treatment is quoted and consented to separately."},{"question":"Does this package guarantee pregnancy?","answer":"No. No assessment can guarantee pregnancy, and no test can detect every possible fertility factor. These packages are designed to give you and your specialist clearer information to work from."},{"question":"Can I book a consultation after receiving my results?","answer":"Yes. A results review with a fertility specialist is part of every assessment package, and you can book further consultations at any point."}]'::jsonb, '{"ideal_for":"Couples assessing both sides together","female_assessment":true,"male_assessment":true,"amh":true,"hormonal_evaluation":true,"ultrasound_afc":"conditional","semen_analysis":true,"specialist_consultation":true,"results_review":true,"personalised_plan":true,"availability":"In-clinic","locations":"Bangalore, Hyderabad"}'::jsonb, 'Users', 'pending_clinical_review', '{"title":"Couples Fertility Assessment | Conceev Health","description":"Assess both partners in one visit — female fertility assessment, semen analysis and a joint fertility specialist consultation with a shared next-step plan.","keywords":["couples fertility test","couple fertility assessment","semen analysis bangalore","male fertility test","fertility check for couples"],"og_title":"Couples Fertility Assessment | Conceev Health","og_description":"Fertility takes two. Assess both partners together and leave with one shared plan.","og_image":null,"schema_type":"Service"}'::jsonb, 3),
('egg-freezing-readiness-check', 'Egg Freezing Readiness Check', 'Fertility Preservation', 'Information before commitment', 'Understand your fertility before deciding whether to freeze your eggs.', 'The first step in egg freezing isn''t freezing your eggs — it''s finding out whether it makes sense for you. This check combines an AMH test and, where applicable, an ultrasound with antral follicle count, then gives you an unhurried conversation with a fertility specialist about suitability, what the process would actually involve, and what it would cost and take. No injections. No commitment. Just the information you''d want before deciding.', 'Understand your fertility before you decide about freezing', 'An assessment and specialist conversation designed to inform your decision — not to push you toward one.', 'individual', 'Women considering egg freezing', '[{"title":"You''re considering egg freezing","description":"But want facts before you commit to anything.","icon":"Snowflake"},{"title":"You''re not ready for children yet","description":"And want to understand your options for later.","icon":"Clock"},{"title":"You want to know if it''s suitable","description":"Egg freezing isn''t the right answer for everyone.","icon":"FileSearch"},{"title":"You want the real cost and timeline","description":"Discussed openly, before you make a decision.","icon":"Receipt"}]'::jsonb, ARRAY['egg-freezing', 'understand']::text[], NULL, NULL, 'placeholder', NULL, 'INR', 'Pricing on request', 'published', false, 'No commitment', 'Single visit', 'in_clinic', ARRAY['Bangalore', 'Hyderabad']::text[], '[]'::jsonb, '[{"id":"assessment","title":"Your assessment","subtitle":"The two measures most relevant to this decision.","variant":"default","items":[{"id":"amh","label":"AMH","description":"A blood marker that may help indicate ovarian reserve — a key input when considering egg freezing.","icon":"FlaskConical"},{"id":"afc","label":"Antral follicle count / ultrasound","description":"A scan that helps your specialist assess follicle numbers, where applicable.","icon":"Scan","conditional":true}]},{"id":"the-conversation","title":"The conversation","subtitle":"Where the decision actually gets made.","variant":"default","items":[{"id":"specialist-consultation","label":"Fertility specialist consultation","description":"Unhurried time with a specialist to ask anything you want.","icon":"Stethoscope"},{"id":"suitability","label":"Egg-freezing suitability discussion","description":"An honest view of whether egg freezing may be appropriate for your situation.","icon":"ClipboardCheck"},{"id":"next-steps","label":"Expected next steps","description":"What the process would involve if you chose to go ahead.","icon":"Route"},{"id":"cost-timeline","label":"Cost and timeline discussion","description":"What it would cost and how long it would take, discussed openly.","icon":"Receipt"}]}]'::jsonb, ARRAY['The egg freezing cycle itself — quoted separately if you choose to proceed', 'Stimulation medication and injections', 'Egg storage fees', 'Investigations beyond those listed, unless agreed with you in advance', 'Treatment at partner hospitals arranged under a separate care plan']::text[], ARRAY['An indication of your ovarian reserve today', 'Whether egg freezing may be appropriate for your situation', 'What the process would realistically involve', 'What it would cost and how long it would take', 'Whether waiting, proceeding or reassessing later may make more sense for you']::text[], '[{"step":"01","title":"Choose your package","description":"Pick the assessment that matches where you are today. Not sure? Our care team can help you decide."},{"step":"02","title":"Book your appointment","description":"Share your details and a care coordinator confirms your slot, location and any preparation you need."},{"step":"03","title":"Complete your assessment","description":"Your AMH test and, where applicable, your scan — in a single visit. No injections and no commitment."},{"step":"04","title":"Decide with a specialist","description":"Talk through your results, suitability, cost and timeline before deciding anything."}]'::jsonb, '[{"question":"Does booking this mean I''m committing to freezing my eggs?","answer":"No. That''s the point of it. This check exists so you can make the decision with information rather than without it, and choosing not to proceed is a completely normal outcome."},{"question":"Does this package guarantee a successful egg freezing outcome?","answer":"No. This is an assessment and consultation only. It may help you and your specialist understand your ovarian reserve and whether egg freezing is worth considering — it cannot predict or guarantee any future outcome, including future pregnancy."},{"question":"Am I too young or too old for this?","answer":"There''s no single right age. Your specialist discusses how your age and results fit together and what that may mean for the timing of any decision."},{"question":"Do I need a doctor''s referral to book?","answer":"No referral is needed. You can book any assessment directly, and a fertility specialist reviews your results with you afterwards."},{"question":"Do I need to fast before my tests?","answer":"It depends on which investigations are included for you. Your care coordinator confirms any fasting or cycle-day requirements when your appointment is scheduled, so you are never left guessing."},{"question":"When will I receive my results?","answer":"Turnaround varies by investigation and by lab. Your coordinator gives you an expected timeline at the time of booking and lets you know as soon as your results are ready for review."},{"question":"How long does the appointment take?","answer":"Your coordinator shares the expected duration for your specific appointment when you book, along with the location and anything you need to bring."},{"question":"Can I add additional tests?","answer":"Yes. If your specialist feels further evaluation may be useful, additional investigations can be discussed and arranged. Any additional cost is confirmed with you before anything is carried out."},{"question":"Does this package include treatment?","answer":"No. These are assessment and consultation packages. They may help you and your specialist understand your situation and decide what to consider next — any treatment is quoted and consented to separately."},{"question":"Does this package guarantee pregnancy?","answer":"No. No assessment can guarantee pregnancy, and no test can detect every possible fertility factor. These packages are designed to give you and your specialist clearer information to work from."},{"question":"Can I book a consultation after receiving my results?","answer":"Yes. A results review with a fertility specialist is part of every assessment package, and you can book further consultations at any point."}]'::jsonb, '{"ideal_for":"Deciding whether to freeze your eggs","female_assessment":true,"male_assessment":false,"amh":true,"hormonal_evaluation":"conditional","ultrasound_afc":"conditional","semen_analysis":false,"specialist_consultation":true,"results_review":true,"personalised_plan":true,"availability":"In-clinic","locations":"Bangalore, Hyderabad"}'::jsonb, 'Snowflake', 'pending_clinical_review', '{"title":"Egg Freezing Readiness Check | Conceev Health","description":"Understand your fertility before deciding whether to freeze your eggs. AMH, antral follicle count where applicable, and an unhurried fertility specialist consultation.","keywords":["egg freezing check","egg freezing readiness","AMH test egg freezing","egg freezing consultation bangalore","fertility preservation"],"og_title":"Egg Freezing Readiness Check | Conceev Health","og_description":"The first step to freezing isn''t freezing. It''s finding out where you stand today.","og_image":null,"schema_type":"Service"}'::jsonb, 4),
('fertility-expert-consultation', 'Fertility Expert Consultation', 'Consultation', 'Ask before you commit', 'Time with a fertility expert to make sense of where you are and what comes next.', 'Sometimes what you need isn''t another test — it''s someone to sit down and explain things properly. This consultation gives you unhurried time with a fertility expert to talk through your history, understand reports you already have, or think out loud about a plan someone has proposed. You choose whether that''s a fertility specialist, a fertility counsellor, or a second opinion on an existing recommendation.', 'Talk to someone who can explain it properly', 'Unhurried time with a fertility expert — to understand your reports, weigh your options, or get a second opinion before you commit.', 'either', 'Anyone with fertility questions', '[{"title":"You''re trying to conceive","description":"And want expert input on where to go from here.","icon":"CalendarHeart"},{"title":"You''re considering IVF or IUI","description":"And want to understand the options before deciding.","icon":"Route"},{"title":"You''re confused by your reports","description":"And want them explained in language that makes sense.","icon":"FileSearch"},{"title":"You want a second opinion","description":"On a diagnosis, a plan, or a quote you''ve been given.","icon":"MessageCircleHeart"}]'::jsonb, ARRAY['speak-expert', 'second-opinion', 'understand', 'egg-freezing']::text[], NULL, NULL, 'placeholder', NULL, 'INR', 'Pricing on request', 'published', false, NULL, 'Single consultation', 'hybrid', ARRAY['Bangalore', 'Hyderabad']::text[], '[{"id":"doctor","label":"Doctor consultation","description":"A fertility specialist, for clinical questions and treatment options."},{"id":"counsellor","label":"Fertility counsellor / coach","description":"For the emotional side, decision-making support and lifestyle questions."},{"id":"second-opinion","label":"Second opinion","description":"A fresh clinical review of existing reports or a proposed treatment plan."}]'::jsonb, '[{"id":"consultation","title":"Your consultation","subtitle":"Choose the kind of expert you need.","variant":"default","items":[{"id":"expert-time","label":"Time with a fertility expert","description":"A specialist, a counsellor, or a second-opinion review — your choice at booking.","icon":"Stethoscope"},{"id":"report-review","label":"Review of your existing reports","description":"Bring what you already have and have it explained in plain language.","icon":"FileSearch"},{"id":"questions","label":"Your questions, answered","description":"No question is too basic. That''s what the time is for.","icon":"MessageCircleHeart"},{"id":"next-steps","label":"A clear view of next steps","description":"What may be worth considering, what can wait, and what to ask next.","icon":"Route"}]}]'::jsonb, ARRAY['Investigations and tests — arranged separately if recommended', 'Fertility treatment (IVF, IUI, ICSI) — quoted separately if you choose to proceed', 'Medication and prescriptions', 'Investigations beyond those listed, unless agreed with you in advance', 'Treatment at partner hospitals arranged under a separate care plan']::text[], ARRAY['What your existing results may indicate', 'Which options are realistically open to you', 'What a proposed treatment plan actually involves', 'Which questions are worth asking before committing', 'Whether further evaluation may be useful']::text[], '[{"step":"01","title":"Choose your expert","description":"A fertility specialist, a fertility counsellor, or a second opinion on an existing plan."},{"step":"02","title":"Book your slot","description":"Share your details and a care coordinator confirms your appointment, online or in-clinic."},{"step":"03","title":"Send anything you have","description":"Existing reports or scans help, but they''re not required — you can book with nothing at all."},{"step":"04","title":"Talk it through","description":"Unhurried time to ask your questions and leave with a clear sense of what comes next."}]'::jsonb, '[{"question":"Do I need test results before booking?","answer":"No. You can book with nothing at all. If you do have previous reports or scans, bringing them means your expert can be more specific."},{"question":"Will I be pushed toward treatment?","answer":"No. The purpose of this consultation is to help you understand your situation. If treatment is worth considering, your expert explains why — and choosing to wait or do nothing is always a valid outcome."},{"question":"Can I do this online?","answer":"Yes. Consultations can be arranged online or in-clinic. Let your care coordinator know which you''d prefer when you book."},{"question":"What''s the difference between the doctor and the counsellor?","answer":"A fertility specialist covers the clinical side — results, investigations and treatment options. A fertility counsellor or coach focuses on the decision-making and emotional side, and on lifestyle questions. Many people find both useful at different points."},{"question":"Do I need to fast before my tests?","answer":"It depends on which investigations are included for you. Your care coordinator confirms any fasting or cycle-day requirements when your appointment is scheduled, so you are never left guessing."},{"question":"When will I receive my results?","answer":"Turnaround varies by investigation and by lab. Your coordinator gives you an expected timeline at the time of booking and lets you know as soon as your results are ready for review."},{"question":"How long does the appointment take?","answer":"Your coordinator shares the expected duration for your specific appointment when you book, along with the location and anything you need to bring."},{"question":"Can I add additional tests?","answer":"Yes. If your specialist feels further evaluation may be useful, additional investigations can be discussed and arranged. Any additional cost is confirmed with you before anything is carried out."},{"question":"Does this package include treatment?","answer":"No. These are assessment and consultation packages. They may help you and your specialist understand your situation and decide what to consider next — any treatment is quoted and consented to separately."},{"question":"Does this package guarantee pregnancy?","answer":"No. No assessment can guarantee pregnancy, and no test can detect every possible fertility factor. These packages are designed to give you and your specialist clearer information to work from."},{"question":"Can I book a consultation after receiving my results?","answer":"Yes. A results review with a fertility specialist is part of every assessment package, and you can book further consultations at any point."}]'::jsonb, '{"ideal_for":"Questions, reports or a second opinion","female_assessment":false,"male_assessment":false,"amh":false,"hormonal_evaluation":false,"ultrasound_afc":false,"semen_analysis":false,"specialist_consultation":true,"results_review":true,"personalised_plan":true,"availability":"Online or in-clinic","locations":"Bangalore, Hyderabad"}'::jsonb, 'MessageCircleHeart', 'pending_clinical_review', '{"title":"Speak to a Fertility Expert | Conceev Health","description":"Book unhurried time with a fertility specialist or counsellor. Understand your reports, weigh your options, or get a second opinion before you commit to treatment.","keywords":["fertility consultation","speak to fertility expert","fertility second opinion","IVF second opinion india","online fertility consultation"],"og_title":"Speak to a Fertility Expert | Conceev Health","og_description":"Unhurried time with a fertility expert, to understand where you are and what comes next.","og_image":null,"schema_type":"Service"}'::jsonb, 5),
('preconception-fertility-wellness', 'Preconception & Fertility Wellness', 'Preconception Care', 'Prepare before you try', 'For planning pregnancy well — not because something is wrong.', 'Most preparation for pregnancy happens after a positive test. This package moves it earlier. It combines a preconception assessment, relevant investigations and a consultation covering lifestyle, nutrition and fertility optimisation — aimed at people who are planning pregnancy and want to go in prepared, whether or not they have any fertility concern at all.', 'Prepare your body before you start trying', 'A preconception assessment and expert guidance on lifestyle, nutrition and fertility optimisation — for planning well, not for fixing a problem.', 'either', 'People planning pregnancy', '[{"title":"You''re planning pregnancy","description":"In the next few months or the next year.","icon":"Sprout"},{"title":"You want to prepare properly","description":"Rather than start figuring it out after a positive test.","icon":"CalendarHeart"},{"title":"You have no known fertility problem","description":"You don''t need one to benefit from preparing well.","icon":"Sparkles"},{"title":"You want lifestyle guidance","description":"Nutrition and habits, grounded in your own assessment.","icon":"Apple"}]'::jsonb, ARRAY['preconception', 'plan-pregnancy', 'understand']::text[], NULL, NULL, 'placeholder', NULL, 'INR', 'Pricing on request', 'published', false, 'Best for Planning', 'Single visit', 'hybrid', ARRAY['Bangalore', 'Hyderabad']::text[], '[]'::jsonb, '[{"id":"assessment","title":"Preconception assessment","subtitle":"A health check aimed at the months before you try.","variant":"default","items":[{"id":"preconception-assessment","label":"Preconception assessment","description":"A structured review of your health, history and readiness for pregnancy.","icon":"ClipboardCheck"},{"id":"investigations","label":"Relevant investigations","description":"Tests selected for your situation, so nothing unnecessary is added.","icon":"TestTube","conditional":true}]},{"id":"guidance","title":"Guidance & optimisation","subtitle":"Practical things you can act on.","variant":"default","items":[{"id":"lifestyle","label":"Lifestyle discussion","description":"Sleep, stress, activity and habits that may be worth adjusting before you try.","icon":"Activity"},{"id":"nutrition","label":"Nutrition guidance","description":"Dietary guidance shaped around your own assessment.","icon":"Apple"},{"id":"optimisation","label":"Fertility optimisation guidance","description":"Evidence-informed steps that may support your reproductive health.","icon":"Sprout"},{"id":"doctor-consultation","label":"Doctor consultation","description":"Time with a clinician to bring it all together into a plan.","icon":"Stethoscope"}]}]'::jsonb, ARRAY['Fertility treatment (IVF, IUI, ICSI) — quoted separately if you choose to proceed', 'Medication and prescriptions', 'Investigations beyond those listed, unless agreed with you in advance', 'Treatment at partner hospitals arranged under a separate care plan']::text[], ARRAY['How your current health may relate to planning a pregnancy', 'Which lifestyle factors may be worth addressing first', 'What nutritional guidance applies to your situation', 'Whether any result may warrant further evaluation', 'A realistic sense of how to prepare over the coming months']::text[], '[{"step":"01","title":"Choose your package","description":"Pick the assessment that matches where you are today. Not sure? Our care team can help you decide."},{"step":"02","title":"Book your appointment","description":"Share your details and a care coordinator confirms your slot, location and any preparation you need."},{"step":"03","title":"Complete your assessment","description":"Attend your visit. Your coordinator tells you exactly what to expect before you arrive."},{"step":"04","title":"Meet your expert","description":"A fertility specialist reviews your results with you and explains the next steps worth discussing."}]'::jsonb, '[{"question":"Is this for people who already have a fertility problem?","answer":"Not specifically. This package is built for people planning pregnancy who may have no fertility concern at all. If your assessment does surface something worth looking at, your clinician explains what further evaluation may be useful."},{"question":"How far ahead should I book this?","answer":"Preparation generally benefits from time. Your clinician discusses a sensible timeline for your situation during the consultation."},{"question":"Can my partner be assessed too?","answer":"Yes. If you''d both like to be assessed, the Couples Fertility Assessment is designed for that — your care coordinator can help you decide which fits better."},{"question":"Do I need a doctor''s referral to book?","answer":"No referral is needed. You can book any assessment directly, and a fertility specialist reviews your results with you afterwards."},{"question":"Do I need to fast before my tests?","answer":"It depends on which investigations are included for you. Your care coordinator confirms any fasting or cycle-day requirements when your appointment is scheduled, so you are never left guessing."},{"question":"When will I receive my results?","answer":"Turnaround varies by investigation and by lab. Your coordinator gives you an expected timeline at the time of booking and lets you know as soon as your results are ready for review."},{"question":"How long does the appointment take?","answer":"Your coordinator shares the expected duration for your specific appointment when you book, along with the location and anything you need to bring."},{"question":"Can I add additional tests?","answer":"Yes. If your specialist feels further evaluation may be useful, additional investigations can be discussed and arranged. Any additional cost is confirmed with you before anything is carried out."},{"question":"Does this package include treatment?","answer":"No. These are assessment and consultation packages. They may help you and your specialist understand your situation and decide what to consider next — any treatment is quoted and consented to separately."},{"question":"Does this package guarantee pregnancy?","answer":"No. No assessment can guarantee pregnancy, and no test can detect every possible fertility factor. These packages are designed to give you and your specialist clearer information to work from."},{"question":"Can I book a consultation after receiving my results?","answer":"Yes. A results review with a fertility specialist is part of every assessment package, and you can book further consultations at any point."}]'::jsonb, '{"ideal_for":"Preparing before you start trying","female_assessment":true,"male_assessment":"conditional","amh":"conditional","hormonal_evaluation":"conditional","ultrasound_afc":false,"semen_analysis":false,"specialist_consultation":true,"results_review":true,"personalised_plan":true,"availability":"In-clinic or online","locations":"Bangalore, Hyderabad"}'::jsonb, 'Sprout', 'pending_clinical_review', '{"title":"Preconception & Fertility Wellness Package | Conceev Health","description":"Plan pregnancy well with a preconception assessment, relevant investigations and expert guidance on lifestyle, nutrition and fertility optimisation.","keywords":["preconception care","preconception checkup india","planning pregnancy health check","fertility wellness package","pre pregnancy test"],"og_title":"Preconception & Fertility Wellness | Conceev Health","og_description":"Prepare your body before you start trying, with a preconception assessment and expert guidance.","og_image":null,"schema_type":"Service"}'::jsonb, 6)
